"""Cross-check native ATLAS/PACK/TRACE against the python reference."""
import random, subprocess, sys, time
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp/t')
import ref
from fib import compile_runs
import image as img

ENGINE='/workspace/tmp/t/engine'

def run(lines):
    p=subprocess.run([ENGINE],input=('\n'.join(lines)+'\n').encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    if p.returncode: raise SystemExit('engine failed: '+p.stderr.decode()[:500])
    return p.stdout.decode().split('\n')

def h(x): return '%032x'%x
def parse_addr(s): return int(s,16)

def atlas_test(rng, rounds=40):
    bad=0
    for it in range(rounds):
        n = rng.choice([0,1,2,5,50,300,3000,30000]) if it<3 else rng.randrange(0,300)
        routes={}
        for _ in range(n):
            length = rng.choice([0,1,3,16,32,64,96,112,124,127,128,128,128])
            start = rng.randrange(0,1<<128)
            start = (start >> (128-length)) << (128-length) if length else 0
            routes[(start,length)] = rng.randrange(0,2147483648)
        lines=['ATLAS %d'%len(routes)]
        lines += ['%s %d %d'%(h(s),l,hop) for (s,l),hop in routes.items()]
        t0=time.time(); out=run(lines); dt=time.time()-t0
        R=int(out[0]); got=[]
        for row in out[1:1+R]:
            a,hp=row.split(); got.append((int(a,16), None if hp=='-1' else int(hp)))
        exp_s,exp_h = ref.ref_runs(routes)
        exp = list(zip(exp_s,exp_h))
        if len(out)!=R+1: bad+=1; print('atlas framing', len(out), R)
        if got!=exp:
            bad+=1
            print('ATLAS MISMATCH n=%d R=%d'%(len(routes),R))
            for a,b in zip(got,exp):
                if a!=b: print('  got',a,'exp',b); break
            print('  lens', got[:5], exp[:5]); break
        # also compare with the submission's own compiler
        s2,h2 = compile_runs(routes)
        if (s2,h2)!=(exp_s,exp_h): bad+=1; print('py compile_runs mismatch'); break
        if dt>3: print('slow atlas', dt)
    print('atlas rounds',rounds,'bad',bad)

def random_layout(R, starts, rng):
    """Random legal tree; returns BFS-ordered layout tuples."""
    def rec(lo, span):
        if span<=8 and (span<2 or rng.random()<0.4):
            return ('leaf', lo, span, ())
        m = rng.randrange(2, min(9,span)+1)
        cuts = sorted(rng.sample(range(lo+1, lo+span), m-1)) if m>1 else []
        bounds=(lo,)+tuple(cuts)+(lo+span,)
        kids=tuple(rec(a,b-a) for a,b in zip(bounds,bounds[1:]))
        return ('node', lo, span, kids)
    tree = rec(0,R)
    order=[tree]; head=0
    while head<len(order):
        nd=order[head]; head+=1; order.extend(nd[3])
    pos={id(nd):i for i,nd in enumerate(order)}
    out=[]
    for nd in order:
        kind,lo,span,kids=nd
        spread = starts[lo+span-1]-starts[lo]
        modes=[0]
        if spread < (1<<64): modes.append(1)
        if spread < (1<<32): modes.append(2)
        mode=rng.choice(modes)
        cached=rng.randrange(2)
        if kind=='leaf':
            out.append((1,mode,cached,lo,span,()))
        else:
            out.append((0,mode,cached,lo,span,tuple(pos[id(k)] for k in kids)))
    return out

def pack_test(rng, rounds=60):
    bad=0
    for it in range(rounds):
        R=rng.randrange(1,65)
        vals=sorted({rng.randrange(1,1<<rng.choice([10,40,70,128])) for _ in range(R-1)}) if R>1 else []
        starts=[0]+vals
        while len(starts)<R:
            x=starts[-1]+rng.randrange(1,1<<40)
            if x>=(1<<128): break
            starts.append(x)
        R=len(starts)
        hops=[rng.choice([None]+list(range(0,1000))) for _ in range(R)]
        layout=random_layout(R,starts,rng)
        A=rng.choice([0,1,5,64,1000])
        addrs=[rng.randrange(0,1<<128) for _ in range(A)]
        # python image
        py=img.build(R,starts,hops,layout)
        lines=['PACK %d %d %d'%(R,len(layout),A)]
        lines+= ['%s %d'%(h(starts[i]), -1 if hops[i] is None else hops[i]) for i in range(R)]
        for kind,mode,cached,lo,span,kids in layout:
            lines.append('%d %d %d %d %d %s'%(lo,span,mode,cached,len(kids),' '.join(str(k) for k in kids)))
        lines+= [h(a) for a in addrs]
        out=run(lines)
        if out[0]!=py.hex:
            bad+=1; print('PACK image mismatch R=%d N=%d'%(R,len(layout)))
            a,b=out[0],py.hex
            for i in range(0,min(len(a),len(b)),2):
                if a[i:i+2]!=b[i:i+2]:
                    print('  byte',i//2,a[i:i+2],b[i:i+2]); break
            print('  len',len(a),len(b))
            break
        # compare answers with python
        for i,addr in enumerate(addrs):
            row=out[1+i].split()
            hop=int(row[0]); run=int(row[1]); plen=int(row[2]); path=[int(x) for x in row[3:]]
            if plen!=len(path): bad+=1; print('path framing'); break
            prun,ppath=img.lookup(py,addr)
            phop=hops[prun]
            if (run,path)!=(prun,ppath) or (hop if hop!=-1 else None)!=(phop if phop is not None else -1):
                bad+=1; print('PACK answer mismatch', (hop,run,path),(phop,prun,ppath)); break
        if bad: break
        # TRACE cross-check
        tout=run(['TRACE %d'%A, py.hex]+[h(a) for a in addrs])
        if [x for x in tout if x.strip()] != [x for x in out[1:1+A] if x.strip()]:
            bad+=1; print('TRACE mismatch'); break
    print('pack rounds',rounds,'bad',bad)

if __name__=='__main__':
    rng=random.Random(int(sys.argv[1]) if len(sys.argv)>1 else 1)
    what=sys.argv[2] if len(sys.argv)>2 else 'all'
    if what in ('all','atlas'): atlas_test(rng, int(sys.argv[3]) if len(sys.argv)>3 else 25)
    if what in ('all','pack'): pack_test(rng, int(sys.argv[3]) if len(sys.argv)>3 else 40)
